package com.pocketmusic.android;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import static org.junit.Assert.*;

public class AccountRecommendationsTest {
 private Context c;private File root;private String prefs;private AccountMusic.Source source;
 @Before public void setup()throws Exception{Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();root=Files.createTempDirectory(app.getCacheDir().toPath(),"account-music-test-").toFile();prefs="account-music-test-"+UUID.randomUUID();c=new ContextWrapper(app){public File getNoBackupFilesDir(){return root;}public File getCacheDir(){return root;}public SharedPreferences getSharedPreferences(String n,int m){return super.getSharedPreferences(prefs,m);}};source=Recommendations.accountSource;}
 @After public void cleanup(){Recommendations.accountSource=source;c.deleteSharedPreferences(prefs);File[] files=root.listFiles();if(files!=null)for(File file:files)file.delete();root.delete();}
 private Track song(String id){return new Track(id,"Account song","Artist",0,true,"");}
 private DiscoveryShelf shelf(String id){return new DiscoveryShelf("Listen again","Account",List.of(song(id)));}
 private JSONObject card(String id,String type)throws Exception{return new JSONObject().put("musicTwoRowItemRenderer",new JSONObject().put("title",new JSONObject().put("runs",new JSONArray().put(new JSONObject().put("text","Your song")))).put("navigationEndpoint",new JSONObject().put("watchEndpoint",new JSONObject().put("videoId",id).put("watchEndpointMusicSupportedConfigs",new JSONObject().put("watchEndpointMusicConfig",new JSONObject().put("musicVideoType",type))))));}
 @Test public void connectedAccountNeverCallsRandomSearchFallback()throws Exception{YouTubeSession.save(c,"SAPISID=synthetic");Recommendations.accountSource=(context,p)->List.of(shelf("abcdefghijk"));Recommendations.fetch(c,"account-test",(q,p)->{throw new AssertionError("Search fallback must not run");});assertEquals("abcdefghijk",Recommendations.cached(c).get(0).id);assertTrue(Recommendations.basis(c).contains("connected"));assertEquals("Listen again",Recommendations.shelves(c).get(0).title);assertTrue(Recommendations.fresh(c));}
 @Test public void failedAccountRefreshKeepsAccountPicksAndDoesNotUseSearch()throws Exception{YouTubeSession.save(c,"SAPISID=synthetic");Recommendations.save(c,Recommendations.scope(c),0,List.of(shelf("abcdefghijk")),0,"account");Recommendations.accountSource=(context,p)->{throw new IOException("Reconnect YouTube");};try{Recommendations.fetch(c,"account-test",(q,p)->{throw new AssertionError("Search fallback must not run");});fail();}catch(IOException expected){}assertEquals("abcdefghijk",Recommendations.cached(c).get(0).id);}
 @Test public void switchingAccountsDuringRefreshDiscardsOldResults()throws Exception{YouTubeSession.save(c,"SAPISID=synthetic-first");Recommendations.accountSource=(context,p)->{YouTubeSession.save(c,"SAPISID=synthetic-second");return List.of(shelf("abcdefghijk"));};Recommendations.fetch(c,"account-test");assertTrue(Recommendations.cached(c).isEmpty());}
 @Test public void duplicateAndHiddenSongsAreFilteredAcrossAccountShelves()throws Exception{YouTubeSession.save(c,"SAPISID=synthetic");MusicTaste.hide(c,"abcdefghijk",true);Recommendations.accountSource=(context,p)->List.of(new DiscoveryShelf("Home","Account",List.of(song("abcdefghijk"),song("12345678901"))),shelf("12345678901"));Recommendations.fetch(c,"account-test");assertEquals(1,Recommendations.cached(c).size());assertEquals("12345678901",Recommendations.cached(c).get(0).id);assertEquals(1,Recommendations.shelves(c).size());}
 @Test public void accountHomeParserRejectsGeneralVideosAndPreservesVerifiedSongs()throws Exception{JSONObject home=new JSONObject().put("musicCarouselShelfRenderer",new JSONObject().put("contents",new JSONArray().put(card("abcdefghijk","MUSIC_VIDEO_TYPE_ATV")).put(card("12345678901","MUSIC_VIDEO_TYPE_UGC")).put(card("zyxwvutsrqp","MUSIC_VIDEO_TYPE_PODCAST_EPISODE")).put(card("abcdefghijk","MUSIC_VIDEO_TYPE_ATV"))));List<DiscoveryShelf> shelves=AccountMusic.parse(home);assertEquals(1,shelves.size());assertEquals(1,shelves.get(0).tracks.size());assertEquals("Your song",shelves.get(0).tracks.get(0).title);}
 @Test public void signedOutAndAmbiguousResponsesAreNotAccountRecommendations()throws Exception{for(JSONObject response:List.of(new JSONObject(),new JSONObject("{responseContext:{mainAppWebResponseContext:{loggedOut:true}}}"))){try{AccountMusic.requireSignedIn(response);fail();}catch(IOException expected){}}AccountMusic.requireSignedIn(new JSONObject("{responseContext:{mainAppWebResponseContext:{loggedOut:false}}}"));}
 @Test public void cookieHeaderAcceptsOnlyYoutubeDomainAndCannotInjectHeaders()throws Exception{Map<String,String> cookies=AccountMusic.cookies("# Netscape HTTP Cookie File\n.youtube.com\tTRUE\t/\tTRUE\t0\tSAPISID\tsynthetic\n.evil.com\tTRUE\t/\tTRUE\t0\tSID\tforeign\n.youtube.com\tTRUE\t/\tTRUE\t0\tBAD\tinjected;value\n");assertEquals(Map.of("SAPISID","synthetic"),cookies);assertTrue(AccountMusic.authorization("synthetic",123).startsWith("SAPISIDHASH 123_"));}
 @Test public void oldSearchFeedCacheIsInvalidatedOnUpgrade(){c.getSharedPreferences("music",0).edit().putInt("discoverySchema",4).putString("musicScope","guest").putString("musicShelves","[]").commit();assertFalse(Recommendations.fresh(c));assertTrue(Recommendations.cached(c).isEmpty());}
 @Test public void webConfigAndAuthorizationUseTheCurrentMusicClient()throws Exception{assertEquals("1.20261029.01.00",AccountMusic.config("{\"INNERTUBE_CLIENT_VERSION\":\"1.20261029.01.00\"}","INNERTUBE_CLIENT_VERSION"));assertEquals("2",AccountMusic.config("{\"SESSION_INDEX\":\"2\"}","SESSION_INDEX"));assertEquals("",AccountMusic.config("{}","SESSION_INDEX"));assertEquals("SAPISIDHASH 123_db7b6da446577a9f675345ef8264431229d89cde",AccountMusic.authorization("synthetic",123));}
}
